class TestVoteHistoryRemovals:
    """.vh must account for .remvote/.removevote/.manipulate, not just .vote."""

    @staticmethod
    def _member(mid, name):
        m = MagicMock(spec=discord.Member)
        m.id = mid
        m.name = name
        m.display_name = name
        return m

    def test_resolve_removed_player(self):
        """The removed player is pulled from the 'Votes Removed' embed description."""
        player = self._member(7, "Bob")
        guild = MagicMock()
        guild.members = [player]
        embed = discord.Embed(
            title="🗳️ Votes Removed",
            description="All votes involving **Bob** have been removed (3 vote(s)).",
        )
        assert voting_cog.Voting._resolve_removed_player(embed, guild) is player

    def test_resolve_removed_player_unknown(self):
        """An unresolvable name yields None instead of raising."""
        guild = MagicMock()
        guild.members = []
        embed = discord.Embed(title="Votes Removed", description="All votes involving **Ghost** have been removed (1 vote(s)).")
        assert voting_cog.Voting._resolve_removed_player(embed, guild) is None

    def test_resolve_target_prefers_mention(self):
        """A mentioned member is used as the vote target."""
        mentioned = self._member(11, "Carol")
        message = MagicMock(spec=discord.Message)
        message.mentions = [mentioned]
        guild = MagicMock()
        guild.members = []
        assert voting_cog.Voting._resolve_target_from_message(message, "someone else", guild) is mentioned

    def test_resolve_target_falls_back_to_name(self):
        """Without a mention the name is matched against display_name."""
        player = self._member(12, "Dave")
        message = MagicMock(spec=discord.Message)
        message.mentions = []
        guild = MagicMock()
        guild.members = [player]
        assert voting_cog.Voting._resolve_target_from_message(message, "dave", guild) is player


class TestSixLynchSessions:
    """Sessions 3-6 are optional, persistent slots (not the old .addlynch)."""

    def test_base_variables_defines_six_sessions(self):
        """Six voting slots exist as first-class config keys."""
        for n in range(1, 7):
            assert f"lynch_channel_name{n}" in base_variables
            assert f"lynch_channel_id{n}" in base_variables
            assert f"lynch_votes{n}" in base_variables

    def test_extra_session_vote_dicts_default_empty(self):
        """The new vote dicts start empty so no KeyError on first use."""
        for n in range(3, 7):
            assert base_variables[f"lynch_votes{n}"] == {}

    def test_second_leader_election_config(self):
        """A second leader election slot exists as a first-class config key."""
        assert base_variables["leader_channel_name2"] == '👑│leader-election-2'
        assert base_variables["leader_channel_id2"] is None
        assert base_variables["leader_votes2"] == {}

    def test_removed_commands_are_gone(self):
        """.addlynch/.rmlynch and the in-memory registry are fully removed."""
        assert not hasattr(voting_cog.Voting, "addlynch")
        assert not hasattr(voting_cog.Voting, "rmlynch")
        assert not hasattr(voting_cog, "extra_lynch_sessions")
        assert not hasattr(voting_cog.Voting, "_extra_session")

    def test_votelist_accepts_all_sessions(self):
        """.votelist exposes lynch1..lynch6 plus both leader elections."""
        src = pathlib.Path(voting_cog.__file__).read_text(encoding="utf-8")
        assert 'f"lynch{i}": f"LYNCH SESSION {i}"' in src
        assert 'session_labels["leader"] = "LEADER ELECTION"' in src
        assert 'session_labels["leader2"] = "LEADER ELECTION 2"' in src

    def test_votelist_looks_up_by_label(self):
        """.votelist <type> picks its own board, not a position in a filtered list."""
        src = pathlib.Path(voting_cog.__file__).read_text(encoding="utf-8")
        assert "label = session_labels[type.lower()]" in src
        assert "if label in embeds_by_label:" in src

    def test_vote_routing_indexes_all_sessions(self):
        """Session votes land in the matching lynch_votesN dict."""
        src = pathlib.Path(voting_cog.__file__).read_text(encoding="utf-8")
        assert 'guild_data[f"lynch_votes{lidx + 1}"]' in src

    def test_resetvotes_clears_all_sessions(self):
        """.resetvotes wipes every lynch session, including 5 and 6."""
        src = pathlib.Path(voting_cog.__file__).read_text(encoding="utf-8")
        assert "for key in LYNCH_SESSION_VOTE_KEYS:" in src
        assert 'guild_data["leader_votes"] = {}' in src
        assert 'guild_data["leader_votes2"] = {}' in src

    def test_remvote_embed_covers_all_sessions(self):
        """The Votes Removed embed is posted to every session and both leaders."""
        src = pathlib.Path(voting_cog.__file__).read_text(encoding="utf-8")
        assert "for channel in [*lynch_channels, leader_channel, leader_channel2]:" in src


PREFIXES = [
    "# LYNCH VOTES 1:",
    "# LYNCH VOTES 2:",
    "# LYNCH VOTES 3:",
    "# LYNCH VOTES 4:",
    "# LYNCH VOTES 5:",
    "# LYNCH VOTES 6:",
    "# LEADER VOTES:",
    "# LEADER VOTES 2:",
]
SESSION_KEYS = [
    "lynch_channel_name1",
    "lynch_channel_name2",
    "lynch_channel_name3",
    "lynch_channel_name4",
    "lynch_channel_name5",
    "lynch_channel_name6",
    "leader_channel_name",
    "leader_channel_name2",
]
VOTE_KEYS = ["lynch_votes1", "lynch_votes2", "lynch_votes3", "lynch_votes4", "lynch_votes5", "lynch_votes6", "leader_votes", "leader_votes2"]


class _FakeHistory:
    """Async-iterable stand-in for Messageable.history (newest first)."""

    def __init__(self, messages):
        self._messages = messages

    def __aiter__(self):
        async def gen():
            for m in self._messages:
                yield m

        return gen()


def _build_ctx():
    """Guild with 8 session channels, 8 existing boards and the voted member."""
    target = MagicMock()
    target.id = 222
    target.mention = "<@222>"

    me = MagicMock()
    me.id = 999

    guild = MagicMock()
    guild.me = me
    guild.get_member = lambda uid: target if uid == 222 else None

    session_channels = []
    for n in range(len(PREFIXES)):
        ch = MagicMock()
        ch.id = n + 1
        ch.name = f"session-{n + 1}"
        session_channels.append(ch)

    vote_count_channel = MagicMock()
    vote_count_channel.id = 500
    vote_count_channel.name = "vote-count"
    vote_count_channel.send = AsyncMock()
    guild.channels = session_channels + [vote_count_channel]

    boards = {}
    for prefix in PREFIXES:
        msg = MagicMock()
        msg.content = f"{prefix}\nstale"
        msg.author = me
        msg.edit = AsyncMock()
        msg.delete = AsyncMock()
        boards[prefix] = msg

    # Newest first, like the real API.
    vote_count_channel.history = MagicMock(
        return_value=_FakeHistory([boards[p] for p in PREFIXES])
    )

    ctx = MagicMock()
    ctx.guild = guild
    ctx.send = AsyncMock()
    return ctx, session_channels, boards, vote_count_channel


def _guild_data():
    return {
        "vote_count_name": "vote-count",
        "lynch_votes1": {},
        "lynch_votes2": {},
        "lynch_votes3": {str(111): 222},
        "lynch_votes4": {},
        "leader_votes": {},
        "leader_votes2": {},
    }


@pytest.mark.asyncio
class TestAggiornaRisultati:
    """The vote-count board must edit in place, not delete and resend."""

    async def _run(self, channel_arg, votes_key="lynch_votes3"):
        ctx, session_channels, boards, vote_count_channel = _build_ctx()
        data = _guild_data()
        data[votes_key] = {"111": 222}

        def fake_get_lynch_channel(guild, guild_data, name_key):
            return session_channels[SESSION_KEYS.index(name_key)]

        with patch.object(voting_cog, "load_guild_data", return_value=data), patch.object(
            voting_cog, "get_lynch_channel", side_effect=fake_get_lynch_channel
        ):
            await voting_cog.Voting.aggiorna_risultati(voting_cog.Voting.__new__(voting_cog.Voting), ctx, channel_arg)

        return boards, vote_count_channel

    @pytest.mark.parametrize("idx", [0, 1, 2, 3, 4, 5, 6, 7])
    async def test_vote_edits_only_its_own_board(self, idx):
        """A vote in any session edits that board and touches nothing else."""
        ctx, session_channels, boards, vote_count_channel = _build_ctx()

        def fake_get_lynch_channel(guild, guild_data, name_key):
            return session_channels[SESSION_KEYS.index(name_key)]

        data = _guild_data()
        data[VOTE_KEYS[idx]] = {"111": 222}

        with patch.object(voting_cog, "load_guild_data", return_value=data), patch.object(
            voting_cog, "get_lynch_channel", side_effect=fake_get_lynch_channel
        ):
            await voting_cog.Voting.aggiorna_risultati(
                voting_cog.Voting.__new__(voting_cog.Voting), ctx, session_channels[idx]
            )

        edited = [p for p in PREFIXES if boards[p].edit.await_count]
        deleted = [p for p in PREFIXES if boards[p].delete.await_count]
        assert edited == [PREFIXES[idx]]
        assert deleted == []
        assert vote_count_channel.send.await_count == 0
        assert "<@222>" in boards[PREFIXES[idx]].edit.await_args.kwargs["content"]
        assert "**1** votes" in boards[PREFIXES[idx]].edit.await_args.kwargs["content"]

    async def test_full_refresh_rebuilds_every_board_in_order(self):
        """Day start / .resetvotes (no channel) still rebuilds all eight."""
        boards, vote_count_channel = await self._run(None)
        for prefix in PREFIXES:
            assert boards[prefix].delete.await_count == 1, prefix
            assert boards[prefix].edit.await_count == 0, prefix
        assert vote_count_channel.send.await_count == len(PREFIXES)

    async def test_leader_vote_edits_leader_board(self):
        """Leader election votes update # LEADER VOTES:."""
        boards, vote_count_channel = await self._run(None)
        assert all(boards[p].delete.await_count == 1 for p in PREFIXES)

    async def test_missing_board_is_created(self):
        """A board that scrolled out of history is reposted."""
        ctx, session_channels, boards, vote_count_channel = _build_ctx()
        boards["# LYNCH VOTES 3:"].content = "something else"
        vote_count_channel.history = MagicMock(return_value=_FakeHistory([]))

        def fake_get_lynch_channel(guild, guild_data, name_key):
            return session_channels[SESSION_KEYS.index(name_key)]

        with patch.object(voting_cog, "load_guild_data", return_value=_guild_data()), patch.object(
            voting_cog, "get_lynch_channel", side_effect=fake_get_lynch_channel
        ):
            await voting_cog.Voting.aggiorna_risultati(
                voting_cog.Voting.__new__(voting_cog.Voting), ctx, session_channels[2]
            )

        assert vote_count_channel.send.await_count == 1
        assert vote_count_channel.send.await_args.args[0].startswith("# LYNCH VOTES 3:")
